#!/usr/bin/env bash
# wp9 session 2 -- generated by scripts/w9_session2_plan.py from session 1's
# decisions (SHA-256 3d0b3f768cc7b06a6adc6de133c3a8a593daceb62cfa252ffd454d2bc546cc29).  Run:  bash /root/autodl-tmp/FE-JEPA/runs/w9/session2/commands.sh
# A complete report: the arm is skipped. An unreadable report is moved aside.
# States without a report: the arm restarts (--reuse-states, recorded in its
# report). Every attempt keeps its log; status.txt time-stamps each attempt.
set -u
cd /root/autodl-tmp/FE-JEPA || exit 1
P=/root/autodl-tmp/FE-JEPA/runs/w9/session2; mkdir -p "$P"
exec 9>"$P/.lock"
if ! flock -n 9; then echo "STOP: session 2 is already running (tmux ls; pgrep -af fejepa.cli)"; exit 1; fi
python - <<'PY' || { echo "STOP: no GPU, or torch is not E1's" | tee -a "$P/status.txt"; exit 1; }
import json, sys, torch
want = json.load(open('records/wp8/e1/e1_2d_base/report.json'))['provenance']['versions']['torch']
print('torch', torch.__version__, '| E1', want, '| cuda', torch.cuda.is_available())
sys.exit(0 if torch.cuda.is_available() and torch.__version__ == want else 1)
PY
run() {
  local log=$1; shift
  [ -e "$P/$log" ] && mv "$P/$log" "$P/$log.$(date +%Y%m%d-%H%M%S)"
  echo "$log start $(date '+%F %T')" >> "$P/status.txt"
  "$@" 2>&1 | tee "$P/$log"; local rc=${PIPESTATUS[0]}
  echo "$log exit=$rc $(date '+%F %T')" | tee -a "$P/status.txt"
}
arm() {
  local name=$1; shift
  local rep="runs/w9/$name/report.json"
  local want=prereg-w9 code
  code=$(python -c 'from fejepa.report import _git_describe as d; print(d())')
  if [ "$code" != "$want" ]; then echo "STOP before $name: the code is $code, not $want" | tee -a "$P/status.txt"; return 1; fi
  if [ -f "$rep" ]; then
    if python -c 'import json,sys; sys.exit(0 if "provenance" in json.load(open(sys.argv[1])) else 1)' "$rep" 2>/dev/null; then
      echo "$name: report exists, skipped" | tee -a "$P/status.txt"; return; fi
    mv "$rep" "$rep.unreadable.$(date +%Y%m%d-%H%M%S)"
    echo "$name: unreadable report moved aside" | tee -a "$P/status.txt"
  fi
  local extra=""
  if ls "runs/w9/$name/e8_states/"*.pt >/dev/null 2>&1 || ls "runs/w9/$name/e8_states/"*.ckpt >/dev/null 2>&1; then
    extra="--reuse-states"; echo "$name: restarting from its states" | tee -a "$P/status.txt"; fi
  run "$name.log" python -m fejepa.cli run-config "$@" $extra
}
arm c1_n1024 configs/w9_c1_n1024.json
arm c1_n25600 configs/w9_c1_n25600.json --workers 3 --activation-checkpointing off
arm b_n1024 configs/w9_b_n1024.json --workers 3 --activation-checkpointing off
arm s_n1024 configs/w9_s_n1024.json --workers 3 --activation-checkpointing off
arm c1_n4096 configs/w9_c1_n4096.json --workers 3 --activation-checkpointing off
cat "$P/status.txt"
